const el=id=>document.getElementById(id);const paramRows=[...el('parameter-rows').rows];el('parameter-search').oninput=()=>{const q=el('parameter-search').value.trim().toLowerCase();let n=0;paramRows.forEach(r=>{r.hidden=!r.textContent.toLowerCase().includes(q);if(!r.hidden)n++});el('parameter-count').textContent=n+' / 48 条参数'};
el('price-rows').innerHTML=researchPrices.map(p=>`<tr><td>${p.interval_end_Asia_Shanghai}</td><td>${Number(p.day_ahead_CNY_per_MWh).toFixed(2)}</td><td>${Number(p.real_time_CNY_per_MWh).toFixed(2)}</td></tr>`).join('');
function chart(){const k=el('price-kind').value;const vals=researchPrices.map(p=>Number(p[k]));const lo=Math.floor(Math.min(...vals)/100)*100,hi=Math.ceil(Math.max(...vals)/100)*100;const x=i=>60+i/95*870,y=v=>255-(v-lo)/(hi-lo)*225;let svg='';for(let v=lo;v<=hi;v+=100)svg+=`<line x1="60" x2="930" y1="${y(v)}" y2="${y(v)}" stroke="${v===0?'#779c8c':'#2e4e43'}"/><text x="50" y="${y(v)+4}" fill="#b3cbbf" text-anchor="end" font-size="12">${v}</text>`;for(const i of [0,23,47,71,95])svg+=`<text x="${x(i)}" y="283" text-anchor="middle" fill="#b3cbbf" font-size="12">${researchPrices[i].interval_end_Asia_Shanghai}</text>`;svg+='<polyline fill="none" stroke="#67d6bf" stroke-width="2.5" points="'+vals.map((v,i)=>x(i)+','+y(v)).join(' ')+'"/>';el('price-chart').innerHTML=svg;el('price-stats').textContent=`最低 ${Math.min(...vals).toFixed(2)} · 最高 ${Math.max(...vals).toFixed(2)} · 简单均值 ${(vals.reduce((a,b)=>a+b,0)/96).toFixed(2)} 元/MWh · 负价 ${vals.filter(v=>v<0).length} 个时段`;inspect()}
function inspect(){const p=researchPrices[Number(el('price-index').value)],k=el('price-kind').value;el('price-detail').textContent=p.interval_end_Asia_Shanghai+' · '+Number(p[k]).toFixed(2)+' 元/MWh（'+(Number(p[k])/1000).toFixed(5)+' 元/kWh）'}el('price-index').oninput=inspect;el('price-kind').onchange=chart;chart();
